// ══════════════════════════════════════════════
// SABİTLER & DURUM
// ══════════════════════════════════════════════
const KAT_MAP = Object.fromEntries(DATA.egitim_kategorileri.map(k=>[k.id,k]));
const TOTAL_KAT = DATA.egitim_kategorileri.length;
let COMPLETED = {};
let DOC_FILTER = 'all';
let EG_FILTER  = 'all';
let PL_USER = null, PL_EG = null;
let WATCHED = false;
let QUIZ = {q:0,score:0,done:false,sorular:[]};

const KC = {Vinç:'#4178B5','Tavan Vinci':'#7B5EA7','Kazı & Nakliye':'#E07F3A',Diğer:'#9A9A9A'};
const AVC = ['#6FAF8F','#4178B5','#E07F3A','#7B5EA7','#D94F4F','#06b6d4','#E07B3A'];
function avc(n){let h=0;for(let c of n)h=(h*31+c.charCodeAt(0))%AVC.length;return AVC[h]}
function ini(n){return n.split(' ').slice(0,2).map(w=>w[0]||'').join('').toUpperCase()}

function loadComp(){
  const s=localStorage.getItem('hr_v4');
  COMPLETED=s?JSON.parse(s):{};
  DATA.personeller.forEach(p=>{
    const eg=DATA.personel_egitimler[p.isim]||{};
    Object.entries(eg).forEach(([id,v])=>{
      const k=p.isim+':'+id;
      if(!COMPLETED[k])COMPLETED[k]={tarih:v.tarih,sure:v.sure};
    });
  });
}
function saveComp(){localStorage.setItem('hr_v4',JSON.stringify(COMPLETED))}
function isDone(isim,id){return!!COMPLETED[isim+':'+id]}
function getDone(isim,id){return COMPLETED[isim+':'+id]||null}
function perDone(isim){return DATA.egitim_kategorileri.filter(k=>isDone(isim,k.id)).length}
function perBelgeSorun(isim){
  const b=DATA.personel_belgeler[isim]||{};
  return Object.values(b).filter(v=>v.durum==='yok'||v.durum==='suresi_doldu').length;
}

// ══════════════════════════════════════════════
// INIT
// ══════════════════════════════════════════════
window.onload=()=>{
  loadComp();
  buildEgFilter();
  updateBadges();
  renderDash();
};

function updateBadges(){
  let evrakB=0,perB=0,uyariB=0,egEksik=0;
  DATA.personeller.forEach(p=>{
    const b=DATA.personel_belgeler[p.isim]||{};
    Object.values(b).forEach(v=>{if(v.durum==='yok'||v.durum==='suresi_doldu')evrakB++});
    egEksik+=TOTAL_KAT-perDone(p.isim);
  });
  DATA.periyodik.forEach(p=>{if(p.durum==='suresi_doldu')perB++});
  uyariB=evrakB+perB;
  document.getElementById('nb-evrak').textContent=evrakB;
  document.getElementById('nb-eg').textContent=egEksik;
  document.getElementById('nb-per').textContent=perB;
  document.getElementById('nb-uyari').textContent=uyariB;
}

