// NAV
// ══════════════════════════════════════════════
const PAGE_NAMES={dash:'Dashboard',per:'Personel',evrak:'Evrak Takibi',egitim:'Eğitimler',periyodik:'Periyodik Muayene',uyarilar:'Kritik Uyarılar',rapor:'Raporlama'};
function nav(id){
  document.querySelectorAll('.pg').forEach(p=>p.classList.remove('active'));
  document.getElementById('pg-'+id).classList.add('active');
  document.querySelectorAll('.nav-i').forEach(n=>n.classList.remove('active'));
  const navMap={dash:0,per:1,evrak:2,egitim:3,periyodik:4,uyarilar:5,rapor:6};
  document.querySelectorAll('.nav-i')[navMap[id]]?.classList.add('active');
  document.getElementById('topbar-title').textContent=PAGE_NAMES[id]||id;
  const renders={dash:renderDash,per:renderPer,evrak:renderEvrak,egitim:renderEg,periyodik:renderPeriyodik,uyarilar:renderUyarilar,rapor:renderRapor};
  renders[id]?.();
}

// ══════════════════════════════════════════════
// KAPSAM İSTATİSTİKLERİ (yardımcı)
// ══════════════════════════════════════════════
function kapsamStats(kapsam){
  const list=DATA.personeller.filter(p=>p.kapsam===kapsam);
  const n=list.length;
  let eg_done=0,eg_total=n*TOTAL_KAT,b_sorun=0;
  list.forEach(p=>{
    eg_done+=perDone(p.isim);
    b_sorun+=perBelgeSorun(p.isim);
  });
  const pct=eg_total?Math.round(eg_done/eg_total*100):0;
  return {n,pct,b_sorun,eg_done,eg_total};
}

// ══════════════════════════════════════════════
// DASHBOARD
// ══════════════════════════════════════════════
function renderDash(){
  // Stats
  const totPer=DATA.personeller.length;
  let evB=0,perB=0,egDone=0,egTot=totPer*TOTAL_KAT;
  DATA.personeller.forEach(p=>{
    const b=DATA.personel_belgeler[p.isim]||{};
    Object.values(b).forEach(v=>{if(v.durum==='yok'||v.durum==='suresi_doldu')evB++});
    egDone+=perDone(p.isim);
  });
  DATA.periyodik.forEach(p=>{if(p.durum==='suresi_doldu')perB++});
  const egPct=Math.round(egDone/egTot*100);

  document.getElementById('dash-stats').innerHTML=`
    <div class="sc"><div class="sc-accent b"></div><div class="sc-ico b"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#4178B5" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></div>
      <div><div class="sc-val b">${totPer}</div><div class="sc-lbl">Toplam Personel</div></div></div>
    <div class="sc"><div class="sc-accent r"></div><div class="sc-ico r"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#D94F4F" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></div>
      <div><div class="sc-val r">${evB}</div><div class="sc-lbl">Evrak Sorunu</div><div class="sc-sub">Eksik veya süresi dolmuş</div></div></div>
    <div class="sc"><div class="sc-accent g"></div><div class="sc-ico g"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#6FAF8F" stroke-width="2"><path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></svg></div>
      <div><div class="sc-val g">${egPct}%</div><div class="sc-lbl">Eğitim Tamamlanma</div><div class="sc-sub">${egDone}/${egTot} kayıt</div></div></div>
    <div class="sc"><div class="sc-accent o"></div><div class="sc-ico o"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#E07F3A" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg></div>
      <div><div class="sc-val o">${perB}</div><div class="sc-lbl">Muayene Süresi Dolmuş</div></div></div>`;

  // Kapsam kartları
  const kapsamlar=['Vinç','Tavan Vinci','Kazı & Nakliye'];
  document.getElementById('kapsam-cards').innerHTML=kapsamlar.map(k=>{
    const s=kapsamStats(k);
    const c=KC[k];
    const pb_c=s.pct>=70?'g':s.pct>=40?'o':'r';
    return `<div class="kapsam-card">
      <div class="kapsam-hd">
        <div class="kapsam-dot" style="background:${c}"></div>
        <div class="kapsam-name">${k}</div>
        <div class="kapsam-count">${s.n} personel</div>
      </div>
      <div class="kapsam-stat-row">
        <div class="kms"><div class="kms-val" style="color:${c}">${s.pct}%</div><div class="kms-lbl">Eğitim</div></div>
        <div class="kms"><div class="kms-val" style="color:${s.b_sorun?'var(--red)':'var(--green-d)'}">${s.b_sorun}</div><div class="kms-lbl">Belge Sorunu</div></div>
        <div class="kms"><div class="kms-val" style="color:#555">${s.n}</div><div class="kms-lbl">Personel</div></div>
      </div>
      <div class="pb"><div class="pb-f ${pb_c}" style="width:${s.pct}%"></div></div>
    </div>`;
  }).join('');

  // Personel tablosu
  document.getElementById('dash-per-body').innerHTML=DATA.personeller.slice(0,8).map(p=>{
    const done=perDone(p.isim),pct=Math.round(done/TOTAL_KAT*100);
    const pb=pct>=70?'g':pct>=40?'o':'r';
    const bs=perBelgeSorun(p.isim);
    const c=avc(p.isim);
    const kc=KC[p.kapsam]||'#999';
    return `<tr onclick="openSlide('${p.isim}')" style="cursor:pointer">
      <td><div style="display:flex;align-items:center;gap:7px"><div class="av av-32" style="background:${c}">${ini(p.isim)}</div>
        <div><div class="tn">${p.isim}</div></div></div></td>
      <td><span style="font-size:10px;font-weight:700;color:${kc}">${p.kapsam}</span></td>
      <td><div class="pb" style="width:70px;margin-bottom:2px"><div class="pb-f ${pb}" style="width:${pct}%"></div></div>
        <div style="font-size:10px;color:var(--text3)">${done}/${TOTAL_KAT}</div></td>
      <td>${bs?`<span class="chip r">${bs} sorun</span>`:'<span class="chip g">Tamam</span>'}</td>
    </tr>`;
  }).join('');

  // Kritik uyarılar (ilk 6)
  const alerts=buildAlerts().slice(0,6);
  const ad=document.getElementById('dash-alerts');
  ad.innerHTML=alerts.length ? alerts.map(a=>`<div class="alert-i ${a.lvl}">${a.icon} <b>${a.isim}</b> — ${a.msg}</div>`).join('')
    : '<div style="text-align:center;color:var(--text3);padding:20px;font-size:12px">✅ Kritik uyarı yok</div>';
}

// ══════════════════════════════════════════════
// UYARI BUILDER
// ══════════════════════════════════════════════
function buildAlerts(){
  const alerts=[];
  DATA.personeller.forEach(p=>{
    const b=DATA.personel_belgeler[p.isim]||{};
    Object.entries(b).forEach(([bid,bv])=>{
      const bt=DATA.belge_turleri.find(x=>x.id===bid);
      if(bv.durum==='suresi_doldu')
        alerts.push({lvl:'r',icon:'🔴',isim:p.isim,msg:`${bt?.ad||bid} süresi dolmuş`,gk:bv.gun_kalan||0,tip:'belge'});
      else if(bv.durum==='yaklasıyor')
        alerts.push({lvl:'o',icon:'🟠',isim:p.isim,msg:`${bt?.ad||bid} ${bv.gun_kalan} gün içinde doluyor`,gk:bv.gun_kalan||99,tip:'belge'});
    });
  });
  DATA.periyodik.forEach(p=>{
    if(p.durum==='suresi_doldu')
      alerts.push({lvl:'r',icon:'🔴',isim:p.isim,msg:`${p.ekipman} periyodik muayene süresi dolmuş`,gk:p.gun_kalan||0,tip:'periyodik'});
    else if(p.durum==='yaklasıyor')
      alerts.push({lvl:'o',icon:'🟠',isim:p.isim,msg:`${p.ekipman} muayene ${p.gun_kalan} gün içinde doluyor`,gk:p.gun_kalan||99,tip:'periyodik'});
  });
  return alerts.sort((a,b)=>a.gk-b.gk);
}

// ══════════════════════════════════════════════
// PERSONEL
// ══════════════════════════════════════════════
function renderPer(){
  const q=(document.getElementById('per-s')?.value||'').toUpperCase();
  const kf=document.getElementById('per-kapsam')?.value||'';
  const isyf=document.getElementById('per-isy')?.value||'';
  const egf=document.getElementById('per-eg-f')?.value||'';
  let list=DATA.personeller.filter(p=>{
    if(q&&!p.isim.toUpperCase().includes(q)&&!(p.gorev||'').toUpperCase().includes(q))return false;
    if(kf&&p.kapsam!==kf)return false;
    if(isyf&&p.is_yeri!==isyf)return false;
    if(egf==='eksik'&&perDone(p.isim)>=TOTAL_KAT)return false;
    if(egf==='tamam'&&perDone(p.isim)<TOTAL_KAT)return false;
    return true;
  });
  const kc_map=KC;
  document.getElementById('per-tbody').innerHTML=list.map(p=>{
    const done=perDone(p.isim),pct=Math.round(done/TOTAL_KAT*100);
    const pb=pct>=70?'g':pct>=40?'o':'r';
    const bs=perBelgeSorun(p.isim);
    const c=avc(p.isim);
    const kc=kc_map[p.kapsam]||'#999';
    const tb=(DATA.personel_toolbox[p.isim]||[]).length;
    return `<tr onclick="openSlide('${p.isim}')" style="cursor:pointer">
      <td><div style="display:flex;align-items:center;gap:8px"><div class="av av-32" style="background:${c}">${ini(p.isim)}</div>
        <div><div class="tn">${p.isim}</div><div class="ts">${p.is_yeri||'—'}</div></div></div></td>
      <td class="ts">${p.gorev||'—'}</td>
      <td><span style="font-size:10px;font-weight:700;color:${kc}">${p.kapsam}</span></td>
      <td class="ts">${p.is_yeri||'—'}</td>
      <td><div class="pb" style="width:80px;margin-bottom:2px"><div class="pb-f ${pb}" style="width:${pct}%"></div></div>
        <div style="font-size:10px;color:var(--text3)">${done}/${TOTAL_KAT} · %${pct}</div></td>
      <td>${bs?`<span class="chip r">${bs} sorun</span>`:'<span class="chip g">Tamam</span>'}</td>
      <td><button class="btn btn-outline btn-sm" onclick="event.stopPropagation();openSlide('${p.isim}')">Detay →</button></td>
    </tr>`;
  }).join('');
  document.getElementById('per-count').textContent=`${list.length} personel`;
}

// ══════════════════════════════════════════════
// EVRAK
// ══════════════════════════════════════════════
function setEvF(f){
  DOC_FILTER=f;
  document.querySelectorAll('[id^="ev-"]').forEach(b=>b.classList.remove('active'));
  document.getElementById('ev-'+f==='all'?'all':f==='yok'?'yok':f==='suresi_doldu'?'dol':'yak')?.classList.add('active');
  renderEvrak();
}
function renderEvrak(){
  const q=(document.getElementById('ev-s')?.value||'').toUpperCase();
  const rows=[];
  DATA.personeller.forEach(p=>{
    const b=DATA.personel_belgeler[p.isim]||{};
    DATA.belge_turleri.forEach(bt=>{
      const bv=b[bt.id];if(!bv)return;
      if(DOC_FILTER!=='all'&&bv.durum!==DOC_FILTER)return;
      if(q&&!p.isim.toUpperCase().includes(q)&&!bt.ad.toUpperCase().includes(q))return;
      rows.push({p,bt,bv});
    });
  });
  const CM={gecerli:['g','✓ Geçerli'],yok:['gr','— Yok'],'suresi_doldu':['r','✗ Dolmuş'],'yaklasıyor':['o','⚠ Yaklaşıyor']};
  document.getElementById('ev-tbody').innerHTML=rows.map(({p,bt,bv})=>{
    const [cc,cl]=CM[bv.durum]||['gr','—'];
    const c=avc(p.isim),kc=KC[p.kapsam]||'#999';
    return `<tr>
      <td><div style="display:flex;align-items:center;gap:7px"><div class="av av-32" style="background:${c}">${ini(p.isim)}</div>
        <span class="tn">${p.isim}</span></div></td>
      <td><span style="font-size:10px;font-weight:700;color:${kc}">${p.kapsam}</span></td>
      <td class="ts">${bt.ad}</td>
      <td><span class="chip ${cc}">${cl}</span></td>
      <td class="ts">${bv.baslangic||'—'}</td>
      <td class="ts">${bv.gecerlilik||'—'}</td>
      <td>${bv.gun_kalan!=null?`<span class="chip ${bv.gun_kalan<0?'r':bv.gun_kalan<30?'r':bv.gun_kalan<90?'o':'g'}">${bv.gun_kalan<0?Math.abs(bv.gun_kalan)+' gün geçti':bv.gun_kalan+' gün'}</span>`:'—'}</td>
    </tr>`;
  }).join('');
  if(!rows.length)document.getElementById('ev-tbody').innerHTML=`<tr><td colspan="7" style="text-align:center;padding:30px;color:var(--text3)">Kayıt bulunamadı</td></tr>`;
  document.getElementById('ev-count').textContent=`${rows.length} kayıt`;
}

// ══════════════════════════════════════════════
// EĞİTİM
// ══════════════════════════════════════════════
function buildEgFilter(){
  const sel=document.getElementById('eg-kat');
  DATA.egitim_kategorileri.forEach(k=>{const o=document.createElement('option');o.value=k.id;o.textContent=k.ad;sel.appendChild(o)});
}
function setEgF(f){
  EG_FILTER=f;
  document.querySelectorAll('[id^="eg-all"],[id^="eg-eksik"],[id^="eg-tamam"]').forEach(b=>b.classList.remove('active'));
  document.getElementById('eg-'+f)?.classList.add('active');
  renderEg();
}
function renderEg(){
  const q=(document.getElementById('eg-s')?.value||'').toUpperCase();
  const kf=document.getElementById('eg-kat')?.value||'';
  const kapsf=document.getElementById('eg-kapsam')?.value||'';
  const katList=kf?DATA.egitim_kategorileri.filter(k=>k.id===kf):DATA.egitim_kategorileri;
  const rows=[];
  DATA.personeller.forEach(p=>{
    if(kapsf&&p.kapsam!==kapsf)return;
    katList.forEach(kat=>{
      const done=isDone(p.isim,kat.id);
      if(EG_FILTER==='eksik'&&done)return;
      if(EG_FILTER==='tamam'&&!done)return;
      if(q&&!p.isim.toUpperCase().includes(q)&&!kat.ad.toUpperCase().includes(q))return;
      rows.push({p,kat,done,eg:getDone(p.isim,kat.id)});
    });
  });
  const kc_map=KC;
  document.getElementById('eg-tbody').innerHTML=rows.map(({p,kat,done,eg})=>{
    const c=avc(p.isim),kc=kc_map[p.kapsam]||'#999';
    return `<tr>
      <td><div style="display:flex;align-items:center;gap:7px"><div class="av av-32" style="background:${c}">${ini(p.isim)}</div>
        <span class="tn">${p.isim}</span></div></td>
      <td><span style="font-size:10px;font-weight:700;color:${kc}">${p.kapsam}</span></td>
      <td class="ts">${kat.ikon} ${kat.ad}</td>
      <td>${done?'<span class="chip g">Tamamlandı</span>':'<span class="chip r">Eksik</span>'}</td>
      <td class="ts">${eg?.tarih||'—'}</td>
      <td class="ts">${eg?.sure?eg.sure+' sa':'—'}</td>
      <td><button class="btn btn-outline btn-sm" onclick="openPl('${p.isim}','${kat.id}')">▶ ${done?'Tekrar':'Başlat'}</button></td>
    </tr>`;
  }).join('');
  if(!rows.length)document.getElementById('eg-tbody').innerHTML=`<tr><td colspan="7" style="text-align:center;padding:30px;color:var(--text3)">Kayıt bulunamadı</td></tr>`;
  document.getElementById('eg-count').textContent=`${rows.length} kayıt`;
}

// ══════════════════════════════════════════════
// PERİYODİK
// ══════════════════════════════════════════════
function renderPeriyodik(){
  const dolan=DATA.periyodik.filter(p=>p.durum==='suresi_doldu');
  const yaklasan=DATA.periyodik.filter(p=>p.durum==='yaklasıyor');
  const tamam=DATA.periyodik.filter(p=>p.durum==='tamamlandi');
  function renderList(items,el){
    el.innerHTML=items.length?items.map(p=>{
      const c=avc(p.isim);
      return `<div class="per-item">
        <div class="av av-32" style="background:${c}">${ini(p.isim)}</div>
        <div class="per-item-info">
          <div class="per-item-n">${p.isim}</div>
          <div class="per-item-s">${p.ekipman} · ${p.tarih}</div>
        </div>
        ${p.gun_kalan<0?`<span class="chip r">${Math.abs(p.gun_kalan)} gün geçti</span>`:p.gun_kalan<=90?`<span class="chip o">${p.gun_kalan} gün</span>`:'<span class="chip g">Geçerli</span>'}
      </div>`;
    }).join(''):'<div style="color:var(--text3);font-size:11px;text-align:center;padding:12px">—</div>';
  }
  renderList(dolan,document.getElementById('per-dolan'));
  renderList(yaklasan,document.getElementById('per-yaklasan'));
  renderList(tamam,document.getElementById('per-tamam'));
}

// ══════════════════════════════════════════════
// KRİTİK UYARILAR
// ══════════════════════════════════════════════
function renderUyarilar(){
  const alerts=buildAlerts();
  const dolan=alerts.filter(a=>a.lvl==='r');
  const yaklasan=alerts.filter(a=>a.lvl==='o');
  function renderA(items,el){
    el.innerHTML=items.length?items.map(a=>
      `<div class="alert-i ${a.lvl}">${a.icon} <b>${a.isim}</b> — ${a.msg}</div>`
    ).join(''):'<div style="color:var(--text3);font-size:11px;text-align:center;padding:12px">✅ Yok</div>';
  }
  renderA(dolan,document.getElementById('uy-dolan'));
  renderA(yaklasan,document.getElementById('uy-yaklasan'));
}

// ══════════════════════════════════════════════
// RAPOR
// ══════════════════════════════════════════════
function renderRapor(){
  // Kapsam büyük kartları
  const kapsamlar=['Vinç','Tavan Vinci','Kazı & Nakliye'];
  document.getElementById('rapor-kapsam').innerHTML=kapsamlar.map(k=>{
    const s=kapsamStats(k),c=KC[k];
    const pb=s.pct>=70?'g':s.pct>=40?'o':'r';
    return `<div class="card">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px">
        <div style="width:12px;height:12px;border-radius:50%;background:${c}"></div>
        <div style="font-size:15px;font-weight:700">${k}</div>
        <div style="margin-left:auto;font-size:11px;color:var(--text3)">${s.n} personel</div>
      </div>
      <div class="g3" style="gap:8px;margin-bottom:14px">
        <div class="kms"><div class="kms-val" style="color:${c}">${s.pct}%</div><div class="kms-lbl">Eğitim</div></div>
        <div class="kms"><div class="kms-val" style="color:${s.b_sorun?'var(--red)':'var(--green-d)'}">${s.b_sorun}</div><div class="kms-lbl">Belge Sorunu</div></div>
        <div class="kms"><div class="kms-val" style="color:#555">${s.eg_done}</div><div class="kms-lbl">Tamamlanan</div></div>
      </div>
      <div class="pb" style="height:6px"><div class="pb-f ${pb}" style="width:${s.pct}%"></div></div>
    </div>`;
  }).join('');

  // Aylık kartlar
  const sorted=Object.entries(DATA.aylik_rapor)
    .filter(([,v])=>v.toolbox>0||v.egitim>0)
    .sort(([a],[b])=>b.localeCompare(a)).slice(0,12);
  const AY_AD=['','Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
  document.getElementById('aylik-cards').innerHTML=sorted.map(([key,v])=>{
    const [yil,ay]=key.split('-');
    const adn=AY_AD[parseInt(ay)]||ay;
    return `<div class="ay-card" style="flex-shrink:0;min-width:130px">
      <div class="ay-card-hd">${adn} ${yil}</div>
      <div class="ay-row"><span style="font-size:18px">🧰</span><div><div class="ay-val">${v.toolbox}</div><div style="font-size:10px;color:var(--text3)">Toolbox</div></div></div>
      <div class="ay-row"><span style="font-size:18px">🎓</span><div><div class="ay-val">${v.egitim}</div><div style="font-size:10px;color:var(--text3)">Eğitim</div></div></div>
    </div>`;
  }).join('');

  // Kapsama göre eğitim
  document.getElementById('rapor-eg-kapsam').innerHTML=['Vinç','Tavan Vinci','Kazı & Nakliye','Diğer'].map(k=>{
    const s=kapsamStats(k),c=KC[k]||'#999';
    const pb=s.pct>=70?'g':s.pct>=40?'o':'r';
    return `<div>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">
        <div style="width:8px;height:8px;border-radius:50%;background:${c};flex-shrink:0"></div>
        <span style="font-size:12px;flex:1">${k}</span>
        <span style="font-size:11px;color:var(--text3)">${s.n} kişi · %${s.pct}</span>
      </div>
      <div class="pb" style="height:5px"><div class="pb-f ${pb}" style="width:${s.pct}%"></div></div>
    </div>`;
  }).join('');

  // Belge durumu
  const bStats={gecerli:0,yok:0,suresi_doldu:0,'yaklasıyor':0};
  DATA.personeller.forEach(p=>{
    const b=DATA.personel_belgeler[p.isim]||{};
    Object.values(b).forEach(v=>bStats[v.durum]=(bStats[v.durum]||0)+1);
  });
  const btot=Object.values(bStats).reduce((a,b)=>a+b,0);
  document.getElementById('rapor-belge').innerHTML=[
    {k:'gecerli',l:'Geçerli',c:'g'},{k:'yaklasıyor',l:'Yaklaşıyor',c:'o'},
    {k:'suresi_doldu',l:'Süresi Dolmuş',c:'r'},{k:'yok',l:'Mevcut Değil',c:'gr'}
  ].map(({k,l,c})=>{
    const n=bStats[k]||0,pct=Math.round(n/btot*100);
    const pb=c==='g'?'g':c==='o'?'o':c==='r'?'r':'';
    return `<div>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">
        <span class="chip ${c}">${l}</span>
        <span style="font-size:11px;color:var(--text3);margin-left:auto">${n} (${pct}%)</span>
      </div>
      ${pb?`<div class="pb" style="height:4px"><div class="pb-f ${pb}" style="width:${pct}%"></div></div>`:''}
    </div>`;
  }).join('');
}

// ══════════════════════════════════════════════
// PERSONEL SLIDE
// ══════════════════════════════════════════════
function openSlide(isim){
  const p=DATA.personeller.find(x=>x.isim===isim);if(!p)return;
  document.getElementById('sl-title').textContent=isim;
  document.getElementById('sl-ov').classList.add('open');
  document.getElementById('sl-panel').classList.add('open');

  const done=perDone(isim),pct=Math.round(done/TOTAL_KAT*100),pb=pct>=70?'g':pct>=40?'o':'r';
  const tb=(DATA.personel_toolbox[isim]||[]).length;
  const c=avc(isim),kc=KC[p.kapsam]||'#999';
  const bs=perBelgeSorun(isim);
  const b=DATA.personel_belgeler[isim]||{};

  let html=`<div class="sl-profile">
    <div class="av av-40" style="background:${c}">${ini(isim)}</div>
    <div class="sl-profile-info">
      <h4>${isim}</h4>
      <p>${p.gorev||'—'} · ${p.is_yeri||'—'}</p>
      <div class="sl-chips">
        <span style="font-size:10px;font-weight:700;color:${kc};background:${kc}18;padding:2px 8px;border-radius:20px">${p.kapsam}</span>
        <span class="chip ${pct>=70?'g':pct>=40?'o':'r'}">${pct}% Eğitim</span>
        ${bs?`<span class="chip r">${bs} Belge Sorunu</span>`:'<span class="chip g">Belge Tamam</span>'}
        <span class="chip b">${tb} Toolbox</span>
      </div>
    </div>
  </div>`;

  // Belgeler
  html+=`<div class="sl-sec"><div class="sl-sec-t">Belgeler & Sertifikalar</div>`;
  DATA.belge_turleri.forEach(bt=>{
    const bv=b[bt.id];if(!bv)return;
    const CM={gecerli:['g','✓ Geçerli'],yok:['gr','— Yok'],suresi_doldu:['r','✗ Dolmuş'],'yaklasıyor':['o','⚠ Yaklaşıyor']};
    const[cc,cl]=CM[bv.durum]||['gr','—'];
    html+=`<div class="doc-r"><div><div class="doc-n">${bt.ad}</div><div class="doc-d">${bv.gecerlilik?'Geçerlilik: '+bv.gecerlilik:'—'}</div></div><span class="chip ${cc}">${cl}</span></div>`;
  });
  html+=`</div>`;

  // Eğitimler
  html+=`<div class="sl-sec"><div class="sl-sec-t">Eğitimler (${done}/${TOTAL_KAT})</div>`;
  DATA.egitim_kategorileri.forEach(kat=>{
    const d=isDone(isim,kat.id),eg=getDone(isim,kat.id);
    html+=`<div class="eg-r" onclick="openPl('${isim}','${kat.id}')">
      <div class="eg-r-ico">${kat.ikon}</div>
      <div style="flex:1;min-width:0"><div class="eg-r-n">${kat.ad}</div><div class="eg-r-d">${eg?.tarih||'Henüz alınmadı'}</div></div>
      ${d?'<span class="chip g" style="font-size:10px">✓</span>':'<span class="chip r" style="font-size:9px;padding:2px 6px">▶</span>'}
    </div>`;
  });
  html+=`</div>`;

  // Son toolbox
  const recentTB=(DATA.personel_toolbox[isim]||[]).slice(-8).reverse();
  if(recentTB.length){
    html+=`<div class="sl-sec"><div class="sl-sec-t">Son Toolbox Brifingleri</div>
      <div style="display:flex;flex-direction:column;gap:4px">
      ${recentTB.map(t=>`<div style="font-size:10px;padding:5px 9px;background:var(--bg);border-radius:5px;display:flex;gap:8px"><span style="color:var(--text3);white-space:nowrap">${t.tarih}</span><span style="color:var(--text2)">${t.konu}</span></div>`).join('')}</div></div>`;
  }

  document.getElementById('sl-body').innerHTML=html;
}
function closeSlide(){
  document.getElementById('sl-ov').classList.remove('open');
  document.getElementById('sl-panel').classList.remove('open');
}

// ══════════════════════════════════════════════
// EĞİTİM PLAYER
// ══════════════════════════════════════════════
function openPl(isim,egId){
  PL_USER=isim;PL_EG=egId;WATCHED=false;
  QUIZ={q:0,score:0,done:false,sorular:[]};
  const kat=KAT_MAP[egId],ic=(DATA.egitim_icerikleri||{})[egId];
  const done=isDone(isim,egId),eg=getDone(isim,egId);
  document.getElementById('pl-ico').textContent=kat?.ikon||'📚';
  document.getElementById('pl-t').textContent=kat?.ad||egId;
  document.getElementById('pl-s').textContent=kat?.sure||'';
  document.getElementById('pl-status').innerHTML=done?'<span class="chip g">Tamamlandı</span>':'<span class="chip r">Eksik</span>';
  document.getElementById('vph-t').textContent=ic?.video_baslik||kat?.ad||'';
  document.getElementById('v-note').textContent=ic?.aciklama||'Eğitim içeriği yükleniyor...';
  document.getElementById('vph').style.display='flex';
  document.getElementById('vframe').style.display='none';
  document.getElementById('vframe').innerHTML='';
  document.getElementById('watch-ctrl').style.display='none';
  document.getElementById('start-btn').style.display='flex';
  document.getElementById('watch-status').textContent='';
  document.getElementById('pl-info').innerHTML=`
    <div style="display:flex;flex-direction:column;gap:8px">
      <div style="background:var(--bg);border-radius:var(--r-sm);padding:10px"><div style="font-size:9px;color:var(--text3);margin-bottom:2px;letter-spacing:.5px;text-transform:uppercase">Eğitim</div><div style="font-size:13px;font-weight:600">${kat?.ad||egId}</div></div>
      <div style="background:var(--bg);border-radius:var(--r-sm);padding:10px"><div style="font-size:9px;color:var(--text3);margin-bottom:2px;letter-spacing:.5px;text-transform:uppercase">Personel</div><div style="font-size:13px;font-weight:600">${isim}</div></div>
      <div style="background:var(--bg);border-radius:var(--r-sm);padding:10px"><div style="font-size:9px;color:var(--text3);margin-bottom:2px;letter-spacing:.5px;text-transform:uppercase">Frekans</div><div style="font-size:13px;font-weight:600">${kat?.sure||'—'}</div></div>
      ${eg?`<div style="background:var(--green-l);border:1px solid #c5e0d0;border-radius:var(--r-sm);padding:10px"><div style="font-size:9px;color:var(--text3);margin-bottom:2px">Son Tamamlama</div><div style="font-size:13px;font-weight:600;color:var(--green-d)">${eg.tarih} · ${eg.sure} sa</div></div>`:''}
      ${done?'<div class="done-box"><h3>🎉 Tebrikler!</h3><p>Bu eğitimi tamamladınız.</p></div>':''}
    </div>`;
  if(ic?.sorular)QUIZ.sorular=ic.sorular;
  renderQuiz();
  ptab('info');
  document.getElementById('pl-ov').classList.add('open');
}
function closePl(e){
  if(e&&e.target!==document.getElementById('pl-ov'))return;
  document.getElementById('pl-ov').classList.remove('open');
  document.getElementById('vframe').innerHTML='';
}
function startVid(){
  const ic=(DATA.egitim_icerikleri||{})[PL_EG];
  document.getElementById('vph').style.display='none';
  const f=document.getElementById('vframe');f.style.display='block';
  f.innerHTML=ic?.video_url?`<iframe src="${ic.video_url}?autoplay=1" width="100%" height="100%" frameborder="0" allow="autoplay;encrypted-media;fullscreen" allowfullscreen style="display:block"></iframe>`
    :`<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:8px;background:var(--bg);min-height:200px"><div style="font-size:36px">🎬</div><div style="font-size:12px;font-weight:600">Video Henüz Eklenmemiş</div><div style="font-size:11px;color:var(--text3)">PDF sekmesinden materyal yükleyin</div></div>`;
  document.getElementById('start-btn').style.display='none';
  document.getElementById('watch-ctrl').style.display='block';
}
function onWatched(){
  WATCHED=true;
  document.getElementById('watch-ctrl').style.display='none';
  document.getElementById('watch-status').textContent='✓ İzleme kaydedildi';
  ptab('quiz');
  toast('Quiz sekmesine geçildi — soruları yanıtlayın','g');
}
function renderQuiz(){
  const qd=document.getElementById('quiz-box'),qs=QUIZ.sorular;
  if(!qs?.length){qd.innerHTML='<div style="text-align:center;color:var(--text3);padding:20px;font-size:12px">Bu eğitim için quiz bulunmuyor</div>';return}
  if(QUIZ.done){
    const pass=QUIZ.score>=Math.ceil(qs.length*.67);
    qd.innerHTML=`<div class="q-res ${pass?'pass':'fail'}"><h3>${pass?'🎉 Geçtiniz!':'❌ Tekrar Deneyin'}</h3><p>${QUIZ.score}/${qs.length} doğru</p></div>
      ${pass?'<div class="done-box"><h3>✅ Eğitim Tamamlandı</h3><p>Başarıyla kaydedildi.</p></div>':''}
      <button class="btn btn-outline" style="width:100%;justify-content:center;margin-top:10px" onclick="resetQ()">↺ Tekrar Dene</button>`;
    if(pass&&WATCHED)markDone();return;
  }
  const i=QUIZ.q,s=qs[i];
  qd.innerHTML=`<div class="quiz-pb"><div class="quiz-pb-f" style="width:${Math.round(i/qs.length*100)}%"></div></div>
    <div class="q-num">Soru ${i+1}/${qs.length}</div>
    <div class="q-q">${s.soru}</div>
    <div class="q-opts">${s.secenekler.map((o,oi)=>`<button class="q-opt" onclick="ansQ(${oi})" ${!WATCHED?'disabled title="Önce videoyu izleyin"':''}>${o}</button>`).join('')}</div>
    ${!WATCHED?'<div style="font-size:10px;color:var(--text3);text-align:center;margin-top:7px">⚠ Quiz için önce videoyu izleyin</div>':''}`;
}
function ansQ(idx){
  const qs=QUIZ.sorular,i=QUIZ.q,s=qs[i];
  document.querySelectorAll('.q-opt').forEach((o,oi)=>{
    o.disabled=true;
    if(oi===s.cevap)o.classList.add('correct');
    else if(oi===idx)o.classList.add('wrong');
  });
  if(idx===s.cevap)QUIZ.score++;
  setTimeout(()=>{QUIZ.q++;if(QUIZ.q>=qs.length)QUIZ.done=true;renderQuiz()},900);
}
function resetQ(){QUIZ={...QUIZ,q:0,score:0,done:false};renderQuiz()}
function markDone(){
  const k=PL_USER+':'+PL_EG;if(COMPLETED[k])return;
  const now=new Date(),tarih=`${String(now.getDate()).padStart(2,'0')}.${String(now.getMonth()+1).padStart(2,'0')}.${now.getFullYear()}`;
  const kat=KAT_MAP[PL_EG];
  COMPLETED[k]={tarih,sure:1,konu:kat?.ad||PL_EG};
  saveComp();updateBadges();
  document.getElementById('pl-status').innerHTML='<span class="chip g">Tamamlandı</span>';
  confetti();toast('🎉 Eğitim tamamlandı ve kaydedildi!','g');
}
function ptab(n){
  ['info','quiz','pdf'].forEach(t=>document.getElementById('ptab-'+t).style.display=t===n?'block':'none');
  document.querySelectorAll('.pt').forEach((b,i)=>b.classList.toggle('active',['info','quiz','pdf'][i]===n));
}
function loadPDF(e){const f=e.target.files[0];if(!f)return;const u=URL.createObjectURL(f);const pf=document.getElementById('pdfV');pf.src=u;pf.style.display='block'}

// ══════════════════════════════════════════════
// YENİ PERSONEL
// ══════════════════════════════════════════════
function openYeniPer(){document.getElementById('modal-new').classList.add('open')}
function closeModal(e){if(e&&e.target!==document.getElementById('modal-new'))return;document.getElementById('modal-new').classList.remove('open')}
function updateChecklist(){
  const kapsam=document.getElementById('new-kapsam').value;
  const wrap=document.getElementById('checklist-wrap');
  if(!kapsam){wrap.style.display='none';return}
  wrap.style.display='block';
  const req=DATA.gorev_gereksinimleri[kapsam]||{belgeler:[],egitimler:[]};
  const BT_AD=Object.fromEntries(DATA.belge_turleri.map(b=>[b.id,b.ad]));
  document.getElementById('cl-belgeler').innerHTML=req.belgeler.map(bid=>`
    <div class="cl-item">
      <div class="cl-ico">📄</div>
      <div class="cl-text">${BT_AD[bid]||bid}</div>
      <div class="cl-status req">Gerekli</div>
    </div>`).join('');
  document.getElementById('cl-egitimler').innerHTML=req.egitimler.map(eid=>{
    const kat=KAT_MAP[eid];
    return `<div class="cl-item">
      <div class="cl-ico">${kat?.ikon||'🎓'}</div>
      <div class="cl-text">${kat?.ad||eid}</div>
      <div class="cl-status req">Gerekli</div>
    </div>`;
  }).join('');
}
function saveNewPer(){
  const isim=document.getElementById('new-isim').value.trim().toUpperCase();
  const kapsam=document.getElementById('new-kapsam').value;
  const gorev=document.getElementById('new-gorev').value.trim();
  const is_yeri=document.getElementById('new-isy').value;
  const tc=document.getElementById('new-tc').value.trim();
  if(!isim||!kapsam){toast('İsim ve kapsam zorunludur!');return}
  DATA.personeller.push({isim,gorev,kapsam,departman:'',yaka:'MAVİ',is_yeri,tc});
  DATA.personel_egitimler[isim]={};
  DATA.personel_toolbox[isim]=[];
  DATA.personel_belgeler[isim]={};
  DATA.belge_turleri.forEach(bt=>{DATA.personel_belgeler[isim][bt.id]={durum:'yok',baslangic:null,gecerlilik:null,gun_kalan:null}});
  closeModal();
  toast(`✓ ${isim} başarıyla eklendi`,'g');
  updateBadges();
  if(document.getElementById('pg-per').classList.contains('active'))renderPer();
}

// ══════════════════════════════════════════════
// YARDIMCILAR
// ══════════════════════════════════════════════
function toast(msg,type=''){
  const t=document.getElementById('toast');t.textContent=msg;t.className='toast'+(type?' '+type:'');t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'),3000);
}
function confetti(){
  const cols=['#6FAF8F','#4178B5','#E07F3A','#7B5EA7','#D94F4F'];
  for(let i=0;i<36;i++){
    const p=document.createElement('div');p.className='cf';
    p.style.cssText=`left:${Math.random()*100}vw;background:${cols[i%cols.length]};width:${5+Math.random()*6}px;height:${5+Math.random()*6}px;border-radius:${Math.random()>.5?'50%':'2px'};animation-delay:${Math.random()*.4}s;animation-duration:${1.5+Math.random()}s`;
    document.body.appendChild(p);setTimeout(()=>p.remove(),2500);
  }
}
function exportCSV(){
  const rows=[['Ad Soyad','Görev','Kapsam','İş Yeri','Eğitim %','Belge Sorunu']];
  DATA.personeller.forEach(p=>{
    const pct=Math.round(perDone(p.isim)/TOTAL_KAT*100);
    rows.push([p.isim,p.gorev,p.kapsam,p.is_yeri,pct+'%',perBelgeSorun(p.isim)]);
  });
  const csv=rows.map(r=>r.map(c=>`"${c}"`).join(',')).join('\n');
  const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,\uFEFF'+encodeURIComponent(csv);
  a.download='hareket_personel.csv';a.click();
  toast('CSV dışa aktarıldı','g');
}